import ta_ue_plugin_android.uepc.adb_proxy as adb
from ta_ue_plugin_android.ue.at_cmds_ue.at_cmds_ue_control import AtCmdsUeControl
from ta_ue_plugin_android.uepc.android_control import AndroidControl
from ta_ue_plugin_android.uepc.ue_pool_on_server import UePool2Backed

QUALCOMM_PREFIX = 'qualcomm'
SOUNDCARD_ANDROID_PREFIX = 'soundcardandroid:'


class ComplexUePool2Backed(UePool2Backed):
    """ComplexUePool2Backed"""

    def __init__(self, ssh_manager):
        """
        Basic initialization.
        :param backends:
        """
        super(ComplexUePool2Backed, self).__init__()
        self.ssh_manager = ssh_manager
        self.backends = {}
        self.backend_that_created_ues = {}

    def cleanup_ue(self, ue_sn, ue):
        """
        :param ue_sn:
        :param ue:
        """
        self.backend_that_created_ues[ue_sn].cleanup_ue(ue_sn, ue)

    def reserve_ue(self, ue_sn):  # pylint: disable=inconsistent-return-statements
        """
        :param ue_sn:
        :return:
        """
        backend = self.create_backend(ue_sn)
        if ue_sn in self.backend_that_created_ues:
            raise Exception("{} UE {} was already reserved at backend.".format(self.get_ue_type(ue_sn), ue_sn))
        if backend.is_ue_sn_available(ue_sn):
            ue = backend.reserve_ue(ue_sn)
            self.backend_that_created_ues[ue_sn] = backend
            return ue

    def unreserve_ue(self, ue_sn, ue_control):  # pylint: disable=arguments-differ
        """
        :param ue_sn:
        :param ue_control:
        """
        self.backend_that_created_ues[ue_sn].unreserve_ue(ue_sn, ue_control)
        del self.backend_that_created_ues[ue_sn]

    def get_ue_type(self, ue_sn):
        """Get UE type"""
        return self.backend_that_created_ues[ue_sn].get_ue_type(ue_sn)

    def create_backend(self, ue_sn):
        """
        Creates backend for the ue based on ue serial number.
        :param ue_sn: UE serial number
        :return: backend instance for the ue type
        """
        self.logger.debug("Creating backend for: {}".format(ue_sn))
        if self.is_android_ue(ue_sn):
            return self._create_backend(AndroidUePool2Backed)
        elif self.is_qualcomm_ue(ue_sn):
            return self._create_backend(QualcommUePool2Backed, self.ssh_manager)
        elif self.is_soundcard_ue(ue_sn):
            return self._create_backend(SoundcardAndroidUePool2Backed)

    def _create_backend(self, backend_type, *args):
        """Return backend with specified type."""
        if backend_type.__name__ in self.backends:
            return self.backends[backend_type.__name__]
        backend_instance = backend_type(*args)
        self.backends[backend_type.__name__] = backend_instance
        return backend_instance

    def is_android_ue(self, ue_sn):
        """
        :param ue_sn:
        :return:
        """
        return True if QUALCOMM_PREFIX not in ue_sn and SOUNDCARD_ANDROID_PREFIX not in ue_sn else False

    def is_soundcard_ue(self, ue_sn):
        """
        :param ue_sn:
        :return:
        """
        return True if SOUNDCARD_ANDROID_PREFIX in ue_sn else False

    def is_qualcomm_ue(self, ue_sn):
        """
        :param ue_sn:
        :return:
        """
        return True if QUALCOMM_PREFIX in ue_sn else False


class AndroidUePool2Backed(UePool2Backed):
    """AndroidUePool2Backed"""

    def __init__(self):
        """Basic initialization."""
        super(AndroidUePool2Backed, self).__init__()
        self.ue_reset_actions = []

    def is_ue_sn_available(self, ue_sn):
        """
        Waits for UE to be visible in adb devices

        :param ue_sn: Ue serial number
        """
        return adb.adb_await_for_ue(ue_sn, wait_time=10)

    def add_ue_reset_action(self, action_callback):
        """
        Add UE reset action.

        :param action_callback:
        """
        self.ue_reset_actions.append(action_callback)

    def list_available_ues(self):
        """
        List available UEs.

        :return:
        """
        devices_list = adb.adb_devices()
        self.logger.debug("AndroidUePool2Backed::list_available_ues() = {}".format(devices_list))
        return devices_list

    def cleanup_ue(self, ue_sn, ue):
        """
        :param ue_sn:
        :param ue:
        """
        self.logger.debug("AndroidUePool2Backed::cleanup_ue({}, {}) starts".format(ue_sn, ue))
        ue.clear_reconnect_queue()
        for action_callback in self.ue_reset_actions:
            action_callback(ue_sn, ue)
        self.logger.debug("AndroidUePool2Backed::cleanup_ue({}, {}) ends".format(ue_sn, ue))

    def reserve_ue(self, ue_sn):
        """
        :param ue_sn:
        :return:
        """
        self.logger.debug("AndroidUePool2Backed::reserve_ue({}) starts".format(ue_sn))
        ue_control = self._new_android_control(ue_sn)
        ue_control.start_ue_manager(ue_sn)
        self.logger.debug("AndroidUePool2Backed::reserve_ue({}) ends".format(ue_sn))
        return ue_control

    def _new_android_control(self, ue_sn):
        return AndroidControl('_' + ue_sn)

    def unreserve_ue(self, ue_sn, ue_control):  # pylint: disable=arguments-differ
        """
        :param ue_sn:
        :param ue_control:
        """
        self.logger.debug("AndroidUePool2Backed::unreserve_ue({}, {}) starts".format(ue_sn, ue_control))
        self.cleanup_ue(ue_sn, ue_control)
        ue_control.release_ue()
        self.logger.debug("AndroidUePool2Backed::unreserve_ue({}, {}) ends".format(ue_sn, ue_control))

    def get_ue_type(self, ue_sn):
        """Get UE type"""
        return "Android"


class SoundcardAndroidUePool2Backed(AndroidUePool2Backed):
    """SoundcardAndroidUePool2Backed"""

    def is_ue_sn_available(self, ue_sn):
        """Is ue sn available"""
        if not ue_sn.startswith(SOUNDCARD_ANDROID_PREFIX):
            return False
        pure_ue_sn = self._extract_pure_serial_number(ue_sn)
        return super(SoundcardAndroidUePool2Backed, self).is_ue_sn_available(pure_ue_sn)

    def _extract_pure_serial_number(self, ue_sn):
        if not ue_sn.startswith(SOUNDCARD_ANDROID_PREFIX):
            raise Exception("serial number of SoundcardAndroidUe has incorrect prefix: {}".format(ue_sn))
        pure_ue_sn = ue_sn[len(SOUNDCARD_ANDROID_PREFIX):]
        return pure_ue_sn

    def reserve_ue(self, ue_sn):
        """
        Parameter ue_sn has to have prefix "soundcardandroid:".
        :param ue_sn:
        :return:
        """
        pure_ue_sn = self._extract_pure_serial_number(ue_sn)
        return super(SoundcardAndroidUePool2Backed, self).reserve_ue(pure_ue_sn)

    def _new_android_control(self, ue_sn):
        # lazy import SoundcardAndroidControl, because SoundcardAndroidControl may raise ImportError
        try:
            from ta_ue_plugin_android.ue.android.uepcsoundcard.soundcard_android_control import SoundcardAndroidControl
        except ImportError:
            from soundcard_android_control import SoundcardAndroidControl
        return SoundcardAndroidControl('_' + ue_sn)

    def get_ue_type(self, ue_sn):
        """Get UE type"""
        return "SoundcardAndroid"

    @staticmethod
    def create_soundcard_serial_number(ue_sn):
        """
        Adds prefix "soundcardandroid:" from constanst SOUNDCARD_ANDROID_PREFIX.
        :param ue_sn:
        :return:
        """
        return "{}{}".format(SOUNDCARD_ANDROID_PREFIX, ue_sn)


class QualcommUePool2Backed(UePool2Backed):
    """QualcommUePool2Backed"""

    def __init__(self, ssh_manager):
        """Basic initialization."""
        super(QualcommUePool2Backed, self).__init__()
        self.ue_reset_actions = []
        self.ssh_manager = ssh_manager

    def add_ue_reset_action(self, action_callback):
        """
        Add UE reset action.

        :param action_callback:
        """
        self.ue_reset_actions.append(action_callback)

    def list_available_ues(self):
        """
        List available UEs.

        :return:
        """
        return []

    def is_ue_sn_available(self, ue_sn):
        """Is ue sn available."""
        return QUALCOMM_PREFIX in ue_sn

    @staticmethod
    def zip_qualcomm_sn(com1, com2, baudrate=None):
        """Zip qualcomm sn"""
        assert ':' not in QUALCOMM_PREFIX
        assert ':' not in com1
        assert ':' not in com2
        suffix = ""
        if baudrate is not None:
            assert ':' not in baudrate
            suffix = ":{}".format(baudrate)
        return "{}:{}:{}".format(QUALCOMM_PREFIX, com1, com2) + suffix

    @staticmethod
    def unzip_qualcomm_sn(sn):
        """Unzip qualcomm sn"""
        try:
            parts = sn.split(':')
            if len(parts) < 3 or len(parts) > 4:
                raise Exception()
            prefix = parts[0]
            com1 = parts[1]
            com2 = parts[2]
            baudrate = None
            if len(parts) >= 4:
                baudrate = parts[3]
            assert prefix == QUALCOMM_PREFIX
            return com1, com2, baudrate
        except Exception:
            raise Exception("Illegal qualcomm sn: " + sn)

    @staticmethod
    def create_serial_number_from_configuration__or_none(configuration):
        """Create qualcomm SN"""
        if 'serial_com' in configuration and 'diag_com' in configuration:
            serial_com = configuration['serial_com']
            diag_com = configuration['diag_com']
            baudrate = None
            if 'serial_baudrate' in configuration:
                baudrate = configuration['serial_baudrate']
            return QualcommUePool2Backed.zip_qualcomm_sn(serial_com, diag_com, baudrate=baudrate)
        return None

    def cleanup_ue(self, ue_sn, ue):
        """
        :param ue_sn:
        :param ue:
        """
        self.logger.debug("QualcommUePool2Backed::cleanup_ue({}, {}) starts".format(ue_sn, ue))
        for action_callback in self.ue_reset_actions:
            action_callback(ue_sn, ue)
        self.logger.debug("QualcommUePool2Backed::cleanup_ue({}, {}) ends".format(ue_sn, ue))

    def reserve_ue(self, ue_sn):
        """
        :param ue_sn:
        :return:
        """
        self.logger.debug("QualcommUePool2Backed::reserve_ue({}) starts".format(ue_sn))
        com1, com2, baudrate = QualcommUePool2Backed.unzip_qualcomm_sn(ue_sn)
        qualcomm_control = AtCmdsUeControl(com1, self.ssh_manager, diag_com=com2, baudrate=baudrate)
        self.action_after_create_qualcomm_control(qualcomm_control)
        self.logger.debug("QualcommUePool2Backed::reserve_ue({}) ends".format(ue_sn))
        return qualcomm_control

    def action_after_create_qualcomm_control(self, qualcomm_control):
        """Action after create qualcomm control."""
        pass

    def unreserve_ue(self, ue_sn, ue_control):  # pylint: disable=arguments-differ
        """
        :param ue_sn:
        :param ue_control:
        """
        self.logger.debug("QualcommUePool2Backed::unreserve_ue({}, {}) starts".format(ue_sn, ue_control))
        self.cleanup_ue(ue_sn, ue_control)
        ue_control.release_ue()
        self.logger.debug("QualcommUePool2Backed::unreserve_ue({}, {}) ends".format(ue_sn, ue_control))

    def get_ue_type(self, ue_sn):
        """Return qualcomm ue type."""
        return "QualcommAt"
